workers = snapshot["workers"]

# 1. Engine concentration
engines = {}
for w in workers:
    e = w["engine"]
    engines[e] = engines.get(e, 0) + 1

# 2. Digest concentration
digests = {}
for w in workers:
    d = w["version_history"][0]["digest"]
    digests[d] = digests.get(d, 0) + 1

# 3. Workers with exceptions / open investigations
issues = []
for w in workers:
    s = w["summary"]
    if s["exceptions"] > 0 or s["last_status"] != "ok" or w.get("investigation"):
        issues.append((w["name"], s["last_status"], s["exceptions"], w.get("investigation")))

# 4. Reservation workers - all refused?
res_workers = [w for w in workers if w["task"] == "reservation"]
for w in res_workers:
    s = w["summary"]
    print(f"{w['name']}: refused={s['rows_refused']}, effects_applied={s['effects_applied']}, effects_failed={s['effects_failed']}, last_status={s['last_status']}")

print("\n--- Engine concentration ---")
for e, c in sorted(engines.items(), key=lambda x: -x[1]):
    print(f"{e}: {c} ({c/70*100:.1f}%)")

print("\n--- Digest concentration ---")
for d, c in sorted(digests.items(), key=lambda x: -x[1]):
    print(f"{d[:12]}...: {c} ({c/70*100:.1f}%)")

print("\n--- Issues ---")
for i in issues:
    print(i)

print("\n--- Reservation effect details ---")
for w in res_workers:
    print(f"\n{w['name']} ({w['customer']}):")
    for r in w["recent_runs"]:
        print(f"  {r['at']}: decision={r.get('decision')}, reason={r.get('reason')}, effect_applied={r.get('effect_applied')}, problems={r.get('problems')}")
